function read(key,fallback){try{return JSON.parse(localStorage.getItem('demotrustmed-'+key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem('demotrustmed-'+key,JSON.stringify(value))}catch{toast('Browser storage is unavailable; changes last for this session.')}}
const initialCart=read('cart',{});let cart={};for(const p of PRODUCTS){const n=Number(initialCart?.[p.id]);if(Number.isInteger(n)&&n>0)cart[p.id]=Math.min(n,20)}
let favourites=read('favourites',[]);if(!Array.isArray(favourites))favourites=[];favourites=favourites.filter(id=>PRODUCTS.some(p=>p.id===id));
let orders=read('orders',[]);if(!Array.isArray(orders))orders=[];let profile=read('profile',null);let selectedFile=null, fileURL=null, detailTab='overview', selectedQty=1, homeCategory='All';let pin=read('pin','');if(!/^\d{6}$/.test(pin))pin='';
